        require(all(q in record['rationale'] for q in terms),'land baseline conditional geography rights or historical limits lost')
        expected_row=copy.deepcopy(case['before_universe_row']);expected_row.update(reason=record['rationale'],rationale=record['rationale'],sources=record['sources'],unresolved_reason=case['new_unresolved_reason']);expected_row['exact_action_source_binding']['source_ids']=[s['source_id'] for s in record['sources']];expected_row['review_progress']['shared_review_record_sha256']=digest(record)
