def validate_title17_same_day_fee_precision(record,row,source,receipt):
    old='fee collection after financial close';new='fee collection on or after financial close';before=receipt['before_record'];expected=copy.deepcopy(before)
    require(receipt['action_id']==record['action_id']=='house:119:1:231' and receipt['rationale_replacement']==[old,new] and before['rationale'].count(old)==1 and receipt['includes_financial_close_day'] and not receipt['fee_offset_interaction_resolved'] and not receipt['current_law_certified'],'Title17 fee same-day boundary or unresolved limits differ')
    expected['rationale']=before['rationale'].replace(old,new)
    require(record==expected and record['disposition']==row['disposition']=='pending_interpretation','Title17 fee correction excluded same-day collection or exceeded exact phrase')
    quote=receipt['source_passage'];require(source['source_id']==receipt['source_id']=='govinfo:42usc16512-2024' and digest(source)==receipt['source_object_sha256'] and source['text'][receipt['source_passage_start']:receipt['source_passage_end']]==quote and 'on or after the date of the financial close' in quote,'Title17 fee correction lacks inclusive source witness')
    expected_row=copy.deepcopy(receipt['before_universe_row']);expected_row.update(reason=record['rationale'],rationale=record['rationale']);expected_row['review_progress']['shared_review_record_sha256']=digest(record)
    require(row==expected_row,'Title17 fee correction changed universe source flags or pending gates')

def validate_title17_export_lengths(manifest,object_bytes,receipt):
    import hashlib
    expected=copy.deepcopy(receipt['original_manifest']);require(len(manifest['objects'])==len(expected['objects'])==7 and not receipt['source_content_integrity_changed'],'Title17 export correction changed source integrity or cohort')
    for i,(old,current) in enumerate(zip(expected['objects'],manifest['objects']),16511):
        require(current['source_id']==f'govinfo:42usc{i}-2024','Title17 export source identity differs')
        body=object_bytes[current['export_path']];old['export_bytes']=len(body)
        require(current['export_bytes']==len(body) and hashlib.sha256(body).hexdigest()==current['export_lf_sha256'],'Title17 exported byte length or preserved hash differs')
    require(manifest==expected,'Title17 export correction exceeded seven length fields')

def validate_retained_attestation_proposals(records,rows,sources,receipt):
    from datetime import datetime
    expected=[f'house:119:1:{i}' for i in [19,84,85,88,89,90,108,115,133,213]]
    require([c['action_id'] for c in receipt['cases']]==expected and receipt['no_source_or_semantic_gate_cleared'] and not receipt['new_shared_meaning_authored'] and receipt['compiled_graph_unchanged'],'attestation proposal cohort or no-clearance boundary differs')
    for case in receipt['cases']:
        aid=case['action_id'];record=records[aid];row=rows[aid];before=case['before_record'];body=sources[case['body_source_id']];clerk=sources[case['clerk_source_id']];md=clerk['metadata'];extent=case['attestation_extent'];quote=case['attestation']
        require(case['proposal_only'] and not case['exact_binding_gate_cleared'] and not case['complete_body_reread'] and record['disposition']==row['disposition']=='pending_interpretation' and record['exact_action_binding_unresolved'] and not row['exact_action_source_binding']['complete'],'attestation metadata proposal cleared an unresolved or semantic gate')
        date=re.fullmatch(r'Passed the House of Representatives ([A-Z][a-z]+ \d{1,2}, \d{4})\.',quote)
        require(date is not None and body['text'][extent['start']:extent['end']]==quote and extent['total']==len(body['text']) and case['body_header_excerpt']==body['text'][:360],'attestation proposal quote or bounded body extent differs')
        require(body['source_type']=='official_bill_text' and body['text_version']=='EH' and body['source_id']==f'govinfo:hr{case["bill_number"]}eh' and f'BILLS-119hr{case["bill_number"]}eh' in body['url'] and re.sub(r'[\s.]','',md['legis-num']).upper()=='HR'+str(case['bill_number']) and md['congress']=='119','attestation proposal official identity/version differs')
        require(md['vote-result']=='Passed' and md['vote-question']=='On Motion to Suspend the Rules and Pass, as Amended' and case['clerk_metadata']=={k:md[k] for k in ['congress','legis-num','action-date','vote-question','vote-result']} and datetime.strptime(date.group(1),'%B %d, %Y').date()==datetime.strptime(md['action-date'],'%d-%b-%Y').date(),'attestation proposal Clerk question/result/date mismatch')
        require(all(digest(sources[sid])==b['source_object_sha256'] for sid,b in case['source_bindings'].items()),'attestation proposal retained source object changed')
        wanted=copy.deepcopy(before);wanted.update(rationale=case['new_rationale'],claim_source_map=before['claim_source_map']+[case['new_claim']]);require(record==wanted and record['rationale'].startswith(before['rationale']+'\n\n') and 'Matching dates alone do not clear those gates' in record['rationale'],'attestation proposal changed prior evidence, flags or material limits')
        claim=case['new_claim'];require(claim['source_id']==body['source_id'] and claim['passage']==quote and 'proposal evidence ONLY' in claim['locator'] and 'DOES NOT clear floor/package reconciliation' in claim['locator'],'attestation proposal became full-body/version clearance')
        wanted_row=copy.deepcopy(case['before_universe_row']);wanted_row.update(reason=record['rationale'],rationale=record['rationale']);wanted_row['review_progress']['shared_review_record_sha256']=digest(record);require(row==wanted_row,'attestation proposal altered prior universe boundary')

def validate_post_act_boundaries(action,sources,recommendation,version):
    require(action['action_id']=='house:119:1:241' and action['source_id']=='govinfo:hr3425eh' and action['stage']=='suspension_and_passage' and action['bill_number']==3425,'POSTAct exact action identity differs')
    clerk=sources['clerk:119:1:241'];body=sources['govinfo:hr3425eh'];baseline=sources['govinfo:40usc1315-2024'];attestation='Passed the House of Representatives September 8, 2025.'
    require(attestation in body['text'] and clerk['metadata']['action-date']=='8-Sep-2025' and clerk['metadata']['vote-result']=='Passed' and clerk['metadata']['vote-question']=='On Motion to Suspend the Rules and Pass, as Amended' and version['body_attestation']==attestation and version['clerk_date']==clerk['metadata']['action-date'] and version['clerk_question']==clerk['metadata']['vote-question'],'POSTAct exact amended House version/date binding differs')
    text=action['meaning'];require(all(x in text for x in ['owned, occupied or secured by the General Services Administration Public Buildings Service','mandatory cause-specific corrective training/performance plans','report is due UPON COMPLETION','first-report trigger is not rewritten as a fixed one-year date','annually thereafter FOR THREE YEARS','OR to implement technical, operational or administrative corrective actions','does not mandate replacement rather than repair','completion of system replacement within that 180-day','HISTORICAL, not revived operative authority','does not designate DHS contractor employees','does not itself confer the statutory officer powers on contractors','not a command that every Facility Security Committee accept every recommendation','membership is an UNACCEPTED candidate']),'POSTAct timing, alternative, scope or historical qualifications lost')
    require('choice between replacement and corrective actions' in action['compact_description'],'POSTAct compact lost nontechnical corrective-action alternative')
